CREATE TABLE public.compliance_flags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.lc_applications(id), screening_status text NOT NULL DEFAULT 'Not Screened', flag_reason text NOT NULL DEFAULT '', risk_priority text NOT NULL DEFAULT 'Normal', review_status text NOT NULL DEFAULT 'Open', decision_reason text, reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.compliance_flags TO authenticated;
GRANT ALL ON public.compliance_flags TO service_role;
ALTER TABLE public.compliance_flags ENABLE ROW LEVEL SECURITY;
CREATE POLICY "customer or staff reads compliance flags" ON public.compliance_flags FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.lc_applications a WHERE a.id = application_id AND (a.customer_id = auth.uid() OR public.is_staff(auth.uid()))));
CREATE TABLE public.tradeflow_settings (key text PRIMARY KEY, value jsonb NOT NULL, updated_by uuid, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.tradeflow_settings TO authenticated;
GRANT ALL ON public.tradeflow_settings TO service_role;
ALTER TABLE public.tradeflow_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin reads settings" ON public.tradeflow_settings FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.email_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_id uuid NOT NULL, application_id uuid, subject text NOT NULL, body text NOT NULL, mode text NOT NULL DEFAULT 'MOCK — NOT SENT', created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.email_outbox TO service_role;
ALTER TABLE public.email_outbox ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.queue_mock_email() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.email_outbox(recipient_id,application_id,subject,body) VALUES (NEW.recipient_id,NEW.application_id,NEW.title,NEW.body); RETURN NEW; END $$;
CREATE TRIGGER tradeflow_mock_email AFTER INSERT ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.queue_mock_email();
CREATE OR REPLACE FUNCTION public.review_compliance_flag(_id uuid,_decision text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE _app uuid; BEGIN IF NOT public.has_role(auth.uid(),'compliance') AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Compliance role required'; END IF; IF _decision NOT IN ('Under Review','Cleared','Escalated') OR length(trim(_reason)) < 3 THEN RAISE EXCEPTION 'Valid decision and reason required'; END IF; UPDATE public.compliance_flags SET review_status = _decision, decision_reason = _reason, reviewed_by = auth.uid(), reviewed_at = now() WHERE id = _id RETURNING application_id INTO _app; IF _app IS NULL THEN RAISE EXCEPTION 'Flag not found'; END IF; INSERT INTO public.audit_logs(application_id,actor_id,action,details) VALUES (_app,auth.uid(),'Compliance ' || _decision,_reason); END $$;
GRANT EXECUTE ON FUNCTION public.review_compliance_flag(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.set_tradeflow_setting(_key text,_value jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin role required'; END IF; IF _key NOT IN ('confidence_thresholds','validation_rules','document_types','workflow_configuration','notification_templates') OR jsonb_typeof(_value) <> 'object' THEN RAISE EXCEPTION 'Invalid setting'; END IF; INSERT INTO public.tradeflow_settings(key,value,updated_by) VALUES (_key,_value,auth.uid()) ON CONFLICT(key) DO UPDATE SET value = EXCLUDED.value, updated_by = auth.uid(),updated_at=now(); END $$;
GRANT EXECUTE ON FUNCTION public.set_tradeflow_setting(text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.assign_tradeflow_role(_user uuid,_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin role required'; END IF; IF _user = auth.uid() THEN RAISE EXCEPTION 'Cannot change your own role'; END IF; IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _user) THEN RAISE EXCEPTION 'User profile not found'; END IF; DELETE FROM public.user_roles WHERE user_id = _user; INSERT INTO public.user_roles(user_id,role) VALUES (_user,_role); END $$;
GRANT EXECUTE ON FUNCTION public.assign_tradeflow_role(uuid,public.app_role) TO authenticated;
CREATE OR REPLACE FUNCTION public.list_tradeflow_users() RETURNS TABLE(id uuid, full_name text, organisation text, role public.app_role) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT p.id,p.full_name,p.organisation,r.role FROM public.profiles p LEFT JOIN public.user_roles r ON r.user_id=p.id WHERE public.has_role(auth.uid(),'admin') ORDER BY p.created_at DESC $$;
GRANT EXECUTE ON FUNCTION public.list_tradeflow_users() TO authenticated;